@import '../../utils/radius.css';
@import '../../utils/control-density.css';
@import '../../utils/chrome-header.css';
@import '../../utils/focus-ring.css';
@import '../../utils/interaction-fill.css';

:host {
  display: block;
  min-width: 0;
  box-sizing: border-box;
  background: var(--_shell-page-header-background, var(--color-background-primary));
}

:host([placement='shell-bar']) {
  --_shell-page-header-background: var(--color-background-secondary);
}

:host-context(ds-shell-app:not([gradient-preset='none']))[placement='shell-bar'],
:host-context(ds-shell-app:not([gradient-preset='none']))[placement='shell-bar'] .bar-title,
:host-context(ds-shell-app.shell-app--paper-texture)[placement='shell-bar'],
:host-context(ds-shell-app.shell-app--paper-texture)[placement='shell-bar'] .bar-title {
  background: transparent;
}

:host([data-shell-page-syncing]) {
  visibility: hidden;
}

.bar-title {
  position: relative;
  min-width: 0;
  box-sizing: border-box;
  background: var(--_shell-page-header-background, var(--color-background-primary));
}

.bar-title::after {
  content: '';
  position: absolute;
  inset: auto var(--ds-bar-title-divider-inset, var(--dimension-space-400)) 0;
  height: var(--dimension-stroke-width-012);
  background: var(--color-border-tertiary);
  pointer-events: none;
}

.bar-title--divider-hidden::after {
  display: none;
}

.bar-title__inner {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: var(--dimension-space-100);
  padding: var(--dimension-space-400);
  box-sizing: border-box;
}

.bar-title__row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--dimension-space-100);
  min-height: var(--dimension-size-400);
  min-width: 0;
}

:host(.bar-title-host--expanded) .bar-title__row {
  gap: var(--dimension-space-400);
}

.bar-title__leading {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  gap: var(--dimension-space-100);
  min-width: 0;
}

.bar-title__title-row {
  display: flex;
  align-items: center;
  gap: var(--dimension-space-100);
  min-width: 0;
  min-height: var(--dimension-size-400);
}

.bar-title__identity {
  display: flex;
  flex: 0 1 auto;
  align-items: center;
  gap: var(--dimension-space-050);
  min-width: 0;
}

.bar-title__back,
.bar-title__section-chevron {
  flex: 0 0 auto;
}

.bar-title__breadcrumb {
  display: block;
  width: 100%;
  min-width: 0;
}

.bar-title__heading {
  display: block;
  width: auto;
  min-width: 0;
  user-select: none;
}

.bar-title__divider {
  width: var(--dimension-stroke-width-012);
  height: var(--dimension-size-250);
  margin-inline-start: var(--dimension-space-100);
  flex: 0 0 var(--dimension-stroke-width-012);
  background: var(--color-border-tertiary);
}

.bar-title__section-selector {
  display: flex;
  flex: 0 1 auto;
  min-width: 0;
  max-width: var(--dimension-panel-width-sm);
}

.bar-title__section-trigger {
  --ds-control-radius: var(--dimension-radius-half);

  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--ds-control-gap);
  height: var(--ds-control-height);
  min-width: 0;
  max-width: 100%;
  padding-inline: var(--ds-control-padding-inline);
  border: none;
  border-radius: var(--ds-control-radius);
  box-sizing: border-box;
  background: transparent;
  color: var(--color-foreground-secondary);
  cursor: default;
  font-family: inherit;
  user-select: none;
}

.bar-title__section-label {
  min-width: 0;
  padding-inline: var(--ds-control-label-inset);
}

.bar-title__actions {
  display: flex;
  align-items: center;
  gap: var(--dimension-space-100);
  flex: 0 0 auto;
}

.bar-title__description {
  display: block;
  min-width: 0;
  max-width: 100%;
}

:host(.bar-title-host--compact) .bar-title {
  height: var(--dimension-size-600);
}

:host(.bar-title-host--compact) .bar-title::after {
  inset-inline: 0;
}

:host(.bar-title-host--compact) .bar-title__inner {
  flex: 1 1 auto;
  height: 100%;
  min-width: 0;
  padding: 0;
  gap: 0;
}

:host(.bar-title-host--compact) .bar-title__row {
  height: 100%;
  align-items: center;
}

:host(.bar-title-host--compact) .bar-title__identity {
  height: var(--dimension-size-400);
}

:host(.bar-title-host--compact) .bar-title__divider {
  margin-inline-start: 0;
}

:host(.bar-title-host--compact) .bar-title__heading {
  display: inline-flex;
  flex: 1 1 auto;
  align-items: center;
  height: var(--dimension-size-400);
  padding-inline: calc(var(--ds-control-padding-inline) + var(--ds-control-label-inset));
  box-sizing: border-box;
}

import {
  Component,
  Element,
  Event,
  EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
} from '@stencil/core';
import type { BreadcrumbItem, BreadcrumbSelectDetail } from '../Breadcrumb/breadcrumb-types';
import type { MenuItemData, MenuSection } from '../Menu/menu-types';
import {
  type BarTitleActionConfigItem,
  type BarTitleActionItem,
  type BarTitlePrimaryAction,
  type BarTitleSectionItem,
  type BarTitlePlacement,
  type BarTitleVariant,
} from './bar-title-types';
import {
  availableBarTitleActionMenuIds,
  barTitleActionIdIssues,
  findBarTitleAction,
  overflowBarTitleActionSections,
  resolveBarTitleActionItems,
  visibleBarTitleActions,
} from './bar-title-actions';
import {
  type FocusableBarTitleButton,
  barTitleActionMenuDomId,
  renderBarTitleActionMenus,
  renderBarTitleActions,
  renderBarTitleBack,
  renderBarTitleOverflowMenu,
  renderBarTitleSectionTrigger,
  restoreBarTitleActionFocus,
} from './bar-title-action-chrome';
import {
  barTitleSectionMenuSections,
  barTitleSectionTriggerAriaLabel,
  effectiveBarTitleSectionValue,
  selectableBarTitleSections,
  selectedBarTitleSectionLabel,
} from './bar-title-sections';

let nextBarTitleId = 0;

@Component({
  tag: 'ds-bar-title',
  styleUrl: 'BarTitle.css',
  scoped: true,
})
export class BarTitle {
  @Element() el!: HTMLElement;

  /** The page's single visible h1. */
  @Prop() heading!: string;

  /** Optional supporting copy shown in the expanded presentation. */
  @Prop() description: string = '';

  /** Show the leading page-level Back action. */
  @Prop({ attribute: 'show-back' }) showBack: boolean = false;

  /** Accessible name for the leading Back action. */
  @Prop() backAriaLabel: string = 'Back';

  /** Visible parent-page label used by the expanded breadcrumb when breadcrumbs is empty. */
  @Prop() backLabel: string = 'Back';

  /** Optional expanded ancestor path. Compact variants continue to use the Back action. */
  @Prop() breadcrumbs: BreadcrumbItem[] = [];

  /** Accessible name for the expanded breadcrumb navigation landmark. */
  @Prop() breadcrumbAriaLabel: string = 'Breadcrumb';

  /** Optional page sections exposed through the active-section menu. */
  @Prop() sections: BarTitleSectionItem[] = [];

  /** Id of the active page section. */
  @Prop() value: string = '';

  /** Accessible name for the page-section menu. */
  @Prop() sectionsAriaLabel: string = 'Change page section';

  /** The one highest-emphasis page action. */
  @Prop() primaryAction: BarTitlePrimaryAction | null = null;

  /** Secondary page actions shown in the overflow menu. Dividers create groups. */
  @Prop() actions: BarTitleActionItem[] = [];

  /**
   * Ordered page-header actions. When supplied, this replaces the legacy
   * primaryAction/actions presentation while preserving the same dsAction event.
   */
  @Prop() actionItems?: BarTitleActionConfigItem[];

  /** Accessible name for the page-actions menu. */
  @Prop() actionsAriaLabel: string = 'More page actions';

  /** Explicit visual/capacity variant. ShellPage owns automatic selection. */
  @Prop() variant: BarTitleVariant = 'expanded';

  /** Page-header placement, or compact application-shell bar placement. */
  @Prop({ reflect: true }) placement: BarTitlePlacement = 'page';

  /** Draw the page-title divider beneath the header. */
  @Prop() showDivider: boolean = true;

  /** Override divider visibility for compact and constrained variants. */
  @Prop() showCompactDivider?: boolean;

  /** Emitted when the leading Back action is activated. */
  @Event() dsBack!: EventEmitter<MouseEvent>;

  /** Emitted when an authored expanded breadcrumb item is activated. */
  @Event({ cancelable: true }) dsBreadcrumbSelect!: EventEmitter<BreadcrumbSelectDetail>;

  /** Emitted with the newly selected page-section id. */
  @Event() dsSectionChange!: EventEmitter<string>;

  /** Emitted with the activated primary or overflow action id. */
  @Event() dsAction!: EventEmitter<string>;

  @State() private sectionMenuOpen = false;
  @State() private openActionMenuId = '';
  @State() private surfaceActionMenuId = '';
  @State() private sectionSurfaceOpen = false;
  @State() private sectionMenuInitialFocusVisible = false;
  @State() private actionMenuInitialFocusVisible = false;

  private readonly instanceId = nextBarTitleId++;
  private readonly sectionMenuTriggerId = `bar-title-section-trigger-${this.instanceId}`;
  private readonly sectionMenuId = `bar-title-section-menu-${this.instanceId}`;
  private readonly actionMenuTriggerId = `bar-title-action-trigger-${this.instanceId}`;
  private readonly actionMenuId = `bar-title-action-menu-${this.instanceId}`;
  private sectionTriggerEl: HTMLButtonElement | null = null;
  private actionTriggerEl: FocusableBarTitleButton | null = null;
  private actionTriggerEls = new Map<string, FocusableBarTitleButton>();

  componentWillLoad() {
    if (this.el.closest('ds-shell-page')) {
      this.el.setAttribute('data-shell-page-syncing', '');
    }
    this.reportActionIdIssues();
  }

  @Watch('sections')
  handleSectionsChange() {
    if (!this.hasSectionSelector) {
      this.closeSectionMenu();
      this.sectionSurfaceOpen = false;
    }
  }

  @Watch('actions')
  @Watch('primaryAction')
  @Watch('actionItems')
  handleActionsChange() {
    this.reportActionIdIssues();
    if (!this.availableActionMenuIds.has(this.openActionMenuId)) this.closeActionMenu();
    if (!this.availableActionMenuIds.has(this.surfaceActionMenuId)) this.surfaceActionMenuId = '';
  }

  private reportActionIdIssues() {
    for (const issue of barTitleActionIdIssues(this.resolvedActionItems)) {
      console.warn(`[ds-bar-title] ${issue}`);
    }
  }

  private get compact(): boolean {
    return this.effectiveVariant !== 'expanded';
  }

  private get effectiveVariant(): BarTitleVariant {
    return this.placement === 'shell-bar' ? 'compact' : this.variant;
  }

  private get dividerVisible(): boolean {
    return this.compact ? (this.showCompactDivider ?? this.showDivider) : this.showDivider;
  }

  private get expandedBreadcrumbItems(): BreadcrumbItem[] {
    if (this.breadcrumbs.length > 0) return this.breadcrumbs;
    if (!this.showBack) return [];
    return [
      {
        id: 'back',
        label: this.backLabel,
        ariaLabel: this.backAriaLabel,
      },
    ];
  }

  private get primaryCollapsed(): boolean {
    return (
      this.actionItems === undefined &&
      this.effectiveVariant === 'constrained' &&
      this.primaryAction !== null &&
      (this.primaryAction.collapse ?? 'auto') === 'auto'
    );
  }

  private get selectableSections() {
    return selectableBarTitleSections(this.sections);
  }

  private get hasSectionSelector(): boolean {
    return this.selectableSections.length > 1;
  }

  private get effectiveValue(): string {
    return effectiveBarTitleSectionValue(this.sections, this.value);
  }

  private get selectedSectionLabel(): string {
    return selectedBarTitleSectionLabel(this.sections, this.value);
  }

  private get sectionTriggerAriaLabel(): string {
    return barTitleSectionTriggerAriaLabel(this.sectionsAriaLabel, this.selectedSectionLabel);
  }

  private get sectionMenuSections() {
    return barTitleSectionMenuSections(this.sections, this.effectiveValue);
  }

  private get resolvedActionItems(): BarTitleActionConfigItem[] {
    return resolveBarTitleActionItems(this.actionItems, this.primaryAction, this.actions);
  }

  private get visibleActions(): BarTitleActionConfigItem[] {
    return visibleBarTitleActions(this.resolvedActionItems, this.effectiveVariant);
  }

  private get actionMenuSections(): MenuSection[] {
    return overflowBarTitleActionSections(this.resolvedActionItems, this.effectiveVariant);
  }

  private get showActionMenuTrigger(): boolean {
    return this.actionMenuSections.length > 0;
  }

  private get availableActionMenuIds(): Set<string> {
    return availableBarTitleActionMenuIds(this.visibleActions, this.showActionMenuTrigger);
  }

  private toggleSectionMenu = (event: MouseEvent) => {
    this.sectionMenuInitialFocusVisible = event.detail === 0;
    this.openActionMenuId = '';
    this.sectionMenuOpen = !this.sectionMenuOpen;
    if (this.sectionMenuOpen) this.sectionSurfaceOpen = true;
  };

  private closeSectionMenu = () => {
    this.sectionMenuOpen = false;
  };

  private handleSectionSelect = (event: CustomEvent<MenuItemData>) => {
    const id = String(event.detail?.value ?? '');
    const selected = this.selectableSections.find(section => section.id === id);
    if (!selected || selected.isInactive) return;
    this.closeSectionMenu();
    this.dsSectionChange.emit(id);
    requestAnimationFrame(() => this.sectionTriggerEl?.focus());
  };

  private toggleActionMenu = (id: string, event: MouseEvent) => {
    this.actionMenuInitialFocusVisible = event.detail === 0;
    this.sectionMenuOpen = false;
    this.openActionMenuId = this.openActionMenuId === id ? '' : id;
    if (this.openActionMenuId) this.surfaceActionMenuId = this.openActionMenuId;
  };

  private finishActionMenuClose = (event: CustomEvent<void>) => {
    const id = this.surfaceActionMenuId;
    const domId =
      id === '__overflow'
        ? this.actionMenuId
        : barTitleActionMenuDomId('bar-title', this.instanceId, this.resolvedActionItems, id);
    if (this.openActionMenuId !== id && (event.target as HTMLElement).id === domId) {
      this.surfaceActionMenuId = '';
    }
  };

  private closeActionMenu = () => {
    this.openActionMenuId = '';
  };

  private handleActionSelect = (event: CustomEvent<MenuItemData>) => {
    const id = String(event.detail?.value ?? '');
    const action = findBarTitleAction(this.resolvedActionItems, id);
    if (!action || action.isInactive || ('isLoading' in action && action.isLoading)) return;
    const menuId = this.openActionMenuId;
    this.closeActionMenu();
    this.dsAction.emit(id);
    requestAnimationFrame(() => {
      void restoreBarTitleActionFocus({
        menuId,
        overflowTrigger: this.actionTriggerEl,
        actionTriggers: this.actionTriggerEls,
        resolvedActionItems: this.resolvedActionItems,
      });
    });
  };

  private chromeActionOptions() {
    return {
      classPrefix: 'bar-title',
      compact: this.compact,
      visibleActions: this.visibleActions,
      showOverflowTrigger: this.showActionMenuTrigger,
      actionItems: this.actionItems,
      primaryAction: this.primaryAction,
      resolvedActionItems: this.resolvedActionItems,
      instanceId: this.instanceId,
      openActionMenuId: this.openActionMenuId,
      surfaceActionMenuId: this.surfaceActionMenuId,
      actionsAriaLabel: this.actionsAriaLabel,
      actionMenuTriggerId: this.actionMenuTriggerId,
      actionMenuId: this.actionMenuId,
      actionTriggers: this.actionTriggerEls,
      setOverflowTriggerEl: (el: FocusableBarTitleButton | null) => {
        this.actionTriggerEl = el;
      },
      toggleActionMenu: this.toggleActionMenu,
      emitAction: (id: string) => this.dsAction.emit(id),
    };
  }

  private renderSectionSelector() {
    if (!this.hasSectionSelector) return null;
    return [
      <div class="bar-title__divider" aria-hidden="true" />,
      renderBarTitleSectionTrigger({
        classPrefix: 'bar-title',
        triggerId: this.sectionMenuTriggerId,
        menuId: this.sectionMenuId,
        open: this.sectionMenuOpen,
        surfaceOpen: this.sectionSurfaceOpen,
        ariaLabel: this.sectionTriggerAriaLabel,
        selectedLabel: this.selectedSectionLabel,
        setTriggerEl: el => {
          this.sectionTriggerEl = el;
        },
        onToggle: this.toggleSectionMenu,
      }),
    ];
  }

  private renderActions() {
    return renderBarTitleActions(this.chromeActionOptions());
  }

  private renderActionMenus() {
    return renderBarTitleActionMenus({
      classPrefix: 'bar-title',
      visibleActions: this.visibleActions,
      instanceId: this.instanceId,
      resolvedActionItems: this.resolvedActionItems,
      openActionMenuId: this.openActionMenuId,
      actionMenuInitialFocusVisible: this.actionMenuInitialFocusVisible,
      overflowTrigger: this.actionTriggerEl,
      actionTriggers: this.actionTriggerEls,
      closeActionMenu: this.closeActionMenu,
      finishActionMenuClose: this.finishActionMenuClose,
      handleActionSelect: this.handleActionSelect,
    });
  }

  private handleBreadcrumbSelect = (event: CustomEvent<BreadcrumbSelectDetail>) => {
    if (this.breadcrumbs.length === 0) {
      this.dsBack.emit(event.detail.originalEvent);
      return;
    }
    const forwarded = this.dsBreadcrumbSelect.emit(event.detail);
    if (forwarded.defaultPrevented) event.preventDefault();
  };

  private renderBreadcrumb() {
    const items = this.expandedBreadcrumbItems;
    if (items.length === 0) return null;
    return (
      <ds-breadcrumb
        class="bar-title__breadcrumb"
        items={items}
        ariaLabel={this.breadcrumbAriaLabel}
        onDsSelect={this.handleBreadcrumbSelect}
      />
    );
  }

  private renderBack() {
    return renderBarTitleBack({
      classPrefix: 'bar-title',
      showBack: this.showBack,
      backAriaLabel: this.backAriaLabel,
      onBack: event => this.dsBack.emit(event),
    });
  }

  render() {
    const compact = this.compact;
    return (
      <Host
        class={{
          'bar-title-host--compact': compact,
          'bar-title-host--expanded': this.effectiveVariant === 'expanded',
          'bar-title-host--constrained': this.effectiveVariant === 'constrained',
          'bar-title-host--has-description': !!this.description,
          'bar-title-host--has-back': this.showBack,
          'bar-title-host--has-breadcrumb': !compact && this.expandedBreadcrumbItems.length > 0,
          'bar-title-host--shell-bar': this.placement === 'shell-bar',
        }}
      >
        <div
          class={{
            'bar-title': true,
            'bar-title--divider-hidden': !this.dividerVisible,
            'ds-chrome-header': compact,
          }}
        >
          <div class="bar-title__inner">
            {!compact ? this.renderBreadcrumb() : null}
            <div class="bar-title__row">
              <div class="bar-title__leading">
                <div class="bar-title__title-row" data-shell-page-header-anchor>
                  <div class="bar-title__identity">
                    {compact ? this.renderBack() : null}
                    <ds-text
                      class="bar-title__heading ds-control--md"
                      variant={compact ? 'text-title-small' : 'text-title-medium'}
                      emphasis
                      color="primary"
                      as="h1"
                      lineTruncation={1}
                    >
                      {this.heading}
                    </ds-text>
                  </div>
                  {this.renderSectionSelector()}
                </div>
                {this.description && !compact ? (
                  <ds-text
                    class="bar-title__description"
                    variant="text-body-small"
                    color="secondary"
                    lineTruncation={2}
                    wrap="wrap"
                    as="p"
                  >
                    {this.description}
                  </ds-text>
                ) : null}
              </div>
              {this.renderActions()}
            </div>
          </div>
        </div>

        {this.hasSectionSelector ? (
          <ds-menu
            id={this.sectionMenuId}
            class="bar-title__section-menu"
            anchorId={this.sectionMenuTriggerId}
            menuLabel={this.sectionsAriaLabel}
            open={this.sectionMenuOpen}
            initialFocusVisible={this.sectionMenuInitialFocusVisible}
            sections={this.sectionMenuSections}
            onDsClose={this.closeSectionMenu}
            onDsAfterClose={() => {
              if (!this.sectionMenuOpen) this.sectionSurfaceOpen = false;
            }}
            onDsSelect={this.handleSectionSelect}
          />
        ) : null}

        {this.renderActionMenus()}

        {renderBarTitleOverflowMenu({
          classPrefix: 'bar-title',
          showOverflowTrigger: this.showActionMenuTrigger,
          actionMenuId: this.actionMenuId,
          actionMenuTriggerId: this.actionMenuTriggerId,
          actionsAriaLabel: this.actionsAriaLabel,
          open: this.openActionMenuId === '__overflow',
          actionMenuInitialFocusVisible: this.actionMenuInitialFocusVisible,
          actionMenuSections: this.actionMenuSections,
          closeActionMenu: this.closeActionMenu,
          finishActionMenuClose: this.finishActionMenuClose,
          handleActionSelect: this.handleActionSelect,
        })}
      </Host>
    );
  }
}

import { h } from '@stencil/core';
import type { MenuItemData, MenuSection } from '../Menu/menu-types';
import { isBarTitleDivider } from './bar-title-types';
import type {
  BarTitleActionConfigItem,
  BarTitleMenuAction,
  BarTitlePrimaryAction,
  BarTitleSplitAction,
} from './bar-title-types';
import { barTitleChoiceSections } from './bar-title-actions';

export type FocusableBarTitleButton = HTMLElement & {
  setFocus?: (segment?: 'primary' | 'menu') => Promise<void>;
};

export function barTitleActionMenuDomId(
  classPrefix: string,
  instanceId: number,
  resolvedActionItems: BarTitleActionConfigItem[],
  id: string
): string {
  const index = resolvedActionItems.findIndex(item => !isBarTitleDivider(item) && item.id === id);
  return `${classPrefix}-action-menu-${instanceId}-${index}`;
}

export function barTitleActionMenuAnchor(
  id: string,
  overflowTrigger: FocusableBarTitleButton | null,
  actionTriggers: Map<string, FocusableBarTitleButton>
): HTMLElement | undefined {
  if (id === '__overflow') return overflowTrigger ?? undefined;
  const trigger = actionTriggers.get(id);
  if (!trigger) return undefined;
  const splitMenu = trigger.querySelector<HTMLElement>('.ds-button-split__menu');
  return splitMenu ?? trigger;
}

export async function restoreBarTitleActionFocus(options: {
  menuId: string;
  overflowTrigger: FocusableBarTitleButton | null;
  actionTriggers: Map<string, FocusableBarTitleButton>;
  resolvedActionItems: BarTitleActionConfigItem[];
}): Promise<void> {
  if (options.menuId === '__overflow') {
    await options.overflowTrigger?.setFocus?.();
    return;
  }
  const trigger = options.actionTriggers.get(options.menuId);
  if (!trigger || !('setFocus' in trigger)) return;
  const split = options.resolvedActionItems.some(
    item => !isBarTitleDivider(item) && item.id === options.menuId && item.type === 'split'
  );
  await trigger.setFocus?.(split ? 'menu' : undefined);
}

function className(prefix: string, part: string): string {
  return `${prefix}__${part}`;
}

export function renderBarTitleBack(options: {
  classPrefix: string;
  showBack: boolean;
  backAriaLabel: string;
  onBack: (event: MouseEvent) => void;
}) {
  if (!options.showBack) return null;
  return (
    <ds-tooltip label="Go back" side="bottom" size="sm">
      <ds-button-unfilled
        class={className(options.classPrefix, 'back')}
        variant="icon"
        icon="ChevronLeft"
        aria-label={options.backAriaLabel}
        size="md"
        activeFill={false}
        hasBorder={false}
        onDsClick={(event: CustomEvent<MouseEvent>) => options.onBack(event.detail)}
      />
    </ds-tooltip>
  );
}

export function renderBarTitleSectionTrigger(options: {
  classPrefix: string;
  triggerId: string;
  menuId: string;
  open: boolean;
  surfaceOpen: boolean;
  ariaLabel: string;
  selectedLabel: string;
  setTriggerEl: (el: HTMLButtonElement | null) => void;
  onToggle: (event: MouseEvent) => void;
}) {
  const prefix = options.classPrefix;
  return (
    <div class={className(prefix, 'section-selector')}>
      <button
        ref={el => {
          options.setTriggerEl((el as HTMLButtonElement | null) ?? null);
        }}
        id={options.triggerId}
        class={{
          [className(prefix, 'section-trigger')]: true,
          [`${className(prefix, 'section-trigger')}--expanded`]: options.open,
          'ds-interaction-fill--surface-open': options.surfaceOpen,
          'ds-control--md': true,
          'ds-focus-ring-inset': true,
          'ds-interaction-fill': true,
        }}
        type="button"
        aria-haspopup="menu"
        aria-controls={options.menuId}
        aria-expanded={String(options.open)}
        aria-label={options.ariaLabel}
        onClick={options.onToggle}
      >
        <ds-text
          class={`${className(prefix, 'section-label')} ds-interaction-fill__content`}
          as="span"
          variant="text-body-medium"
          emphasis
          color="primary"
          lineTruncation={1}
        >
          {options.selectedLabel}
        </ds-text>
        <ds-icon
          class={`${className(prefix, 'section-chevron')} ds-interaction-fill__content`}
          name="ChevronUpDown"
          size="md"
          color="inherit"
          aria-hidden="true"
        />
      </button>
    </div>
  );
}

function renderVisibleAction(
  action: BarTitleActionConfigItem,
  options: {
    classPrefix: string;
    compact: boolean;
    actionItems: BarTitleActionConfigItem[] | undefined;
    primaryAction: BarTitlePrimaryAction | null;
    resolvedActionItems: BarTitleActionConfigItem[];
    instanceId: number;
    openActionMenuId: string;
    surfaceActionMenuId: string;
    actionTriggers: Map<string, FocusableBarTitleButton>;
    toggleActionMenu: (id: string, event: MouseEvent) => void;
    emitAction: (id: string) => void;
  }
) {
  if (isBarTitleDivider(action) || action.type === 'overflow') return null;
  const appearance = action.appearance ?? (action.type === 'split' ? 'filled' : 'unfilled');
  const variant: 'icon' | 'icon-label' | 'label' =
    action.type === 'icon' ? 'icon' : action.icon ? 'icon-label' : 'label';
  const menu = action.type === 'menu';
  const menuId = menu
    ? barTitleActionMenuDomId(
        options.classPrefix,
        options.instanceId,
        options.resolvedActionItems,
        action.id
      )
    : undefined;
  const prefix = options.classPrefix;

  if (action.type === 'split') {
    const splitMenuId = barTitleActionMenuDomId(
      options.classPrefix,
      options.instanceId,
      options.resolvedActionItems,
      action.id
    );
    const splitProps = {
      key: action.id,
      ref: (el: FocusableBarTitleButton | undefined) => {
        if (el) options.actionTriggers.set(action.id, el);
        else options.actionTriggers.delete(action.id);
      },
      class: `${className(prefix, 'action')} ${className(prefix, 'split-action')}`,
      split: true,
      variant,
      label: action.label,
      icon: action.icon ?? '',
      menuAriaLabel: action.menuAriaLabel,
      controls: splitMenuId,
      expanded: options.openActionMenuId === action.id,
      surfaceOpen: options.surfaceActionMenuId === action.id,
      size: 'md' as const,
      type: action.buttonType ?? 'button',
      isInactive: action.isInactive,
      isLoading: action.isLoading,
      onDsClick: () => options.emitAction(action.id),
      onDsMenuClick: (event: CustomEvent<MouseEvent>) =>
        options.toggleActionMenu(action.id, event.detail),
    };
    return appearance === 'filled' ? (
      <ds-button-filled
        {...splitProps}
        intent={action.intent ?? 'brand'}
        contrast={action.contrast ?? 'bold'}
      />
    ) : (
      <ds-button-unfilled {...splitProps} />
    );
  }

  const buttonProps = {
    key: action.id,
    ref: (el: FocusableBarTitleButton | undefined) => {
      if (el) options.actionTriggers.set(action.id, el);
      else options.actionTriggers.delete(action.id);
    },
    class: `${className(prefix, 'action')} ${className(prefix, 'action')}--${action.type}${
      options.actionItems === undefined && action.id === options.primaryAction?.id
        ? ` ${className(prefix, 'primary-action')}`
        : ''
    }`,
    variant,
    icon: action.icon ?? '',
    label: action.label,
    ariaLabel: action.ariaLabel ?? (action.type === 'icon' ? action.label : undefined),
    size: 'md' as const,
    type: action.buttonType ?? 'button',
    isInactive: action.isInactive,
    isLoading: action.isLoading,
    controls: menuId,
    expanded: menu ? options.openActionMenuId === action.id : undefined,
    surfaceOpen: menu && options.surfaceActionMenuId === action.id,
    hasMenu: menu,
    onDsClick: (event: CustomEvent<MouseEvent>) => {
      if (menu) options.toggleActionMenu(action.id, event.detail);
      else options.emitAction(action.id);
    },
  };

  const button =
    appearance === 'filled' ? (
      <ds-button-filled
        {...buttonProps}
        intent={action.intent ?? 'brand'}
        contrast={action.contrast ?? 'bold'}
      />
    ) : (
      <ds-button-unfilled {...buttonProps} />
    );

  return action.type === 'icon' ? (
    <ds-tooltip key={action.id} label={action.label} side="bottom" size="sm">
      {button}
    </ds-tooltip>
  ) : (
    button
  );
}

export function renderBarTitleActions(options: {
  classPrefix: string;
  compact: boolean;
  visibleActions: BarTitleActionConfigItem[];
  showOverflowTrigger: boolean;
  actionItems: BarTitleActionConfigItem[] | undefined;
  primaryAction: BarTitlePrimaryAction | null;
  resolvedActionItems: BarTitleActionConfigItem[];
  instanceId: number;
  openActionMenuId: string;
  surfaceActionMenuId: string;
  actionsAriaLabel: string;
  actionMenuTriggerId: string;
  actionMenuId: string;
  actionTriggers: Map<string, FocusableBarTitleButton>;
  setOverflowTriggerEl: (el: FocusableBarTitleButton | null) => void;
  toggleActionMenu: (id: string, event: MouseEvent) => void;
  emitAction: (id: string) => void;
}) {
  if (options.visibleActions.length === 0 && !options.showOverflowTrigger) return null;
  const prefix = options.classPrefix;

  return (
    <div class={className(prefix, 'actions')}>
      {options.visibleActions.map(action => renderVisibleAction(action, options))}
      {options.showOverflowTrigger ? (
        <ds-tooltip label="Page options" side="bottom" size="sm">
          <ds-button-unfilled
            ref={el => {
              options.setOverflowTriggerEl((el as FocusableBarTitleButton | null) ?? null);
            }}
            id={options.actionMenuTriggerId}
            class={className(prefix, 'more-actions')}
            variant="icon"
            icon="Ellipses"
            aria-label={options.actionsAriaLabel}
            size="md"
            activeFill={!options.compact}
            hasBorder={options.visibleActions.length > 0}
            haspopup="menu"
            controls={options.actionMenuId}
            expanded={options.openActionMenuId === '__overflow'}
            surfaceOpen={options.surfaceActionMenuId === '__overflow'}
            onDsClick={(event: CustomEvent<MouseEvent>) =>
              options.toggleActionMenu('__overflow', event.detail)
            }
          />
        </ds-tooltip>
      ) : null}
    </div>
  );
}

export function renderBarTitleActionMenus(options: {
  classPrefix: string;
  visibleActions: BarTitleActionConfigItem[];
  instanceId: number;
  resolvedActionItems: BarTitleActionConfigItem[];
  openActionMenuId: string;
  actionMenuInitialFocusVisible: boolean;
  overflowTrigger: FocusableBarTitleButton | null;
  actionTriggers: Map<string, FocusableBarTitleButton>;
  closeActionMenu: () => void;
  finishActionMenuClose: (event: CustomEvent<void>) => void;
  handleActionSelect: (event: CustomEvent<MenuItemData>) => void;
}) {
  const prefix = options.classPrefix;
  return options.visibleActions.flatMap(action => {
    if (isBarTitleDivider(action) || (action.type !== 'menu' && action.type !== 'split')) {
      return [];
    }
    const menuAction = action as BarTitleMenuAction | BarTitleSplitAction;
    const menuLabel = menuAction.menuAriaLabel ?? menuAction.ariaLabel ?? menuAction.label;
    return [
      <ds-menu
        key={action.id}
        id={barTitleActionMenuDomId(
          options.classPrefix,
          options.instanceId,
          options.resolvedActionItems,
          action.id
        )}
        class={className(prefix, 'action-menu')}
        anchor={barTitleActionMenuAnchor(
          action.id,
          options.overflowTrigger,
          options.actionTriggers
        )}
        align="end"
        menuLabel={menuLabel}
        open={options.openActionMenuId === action.id}
        initialFocusVisible={options.actionMenuInitialFocusVisible}
        sections={barTitleChoiceSections(menuAction.choices)}
        onDsClose={options.closeActionMenu}
        onDsAfterClose={options.finishActionMenuClose}
        onDsSelect={options.handleActionSelect}
      />,
    ];
  });
}

export function renderBarTitleOverflowMenu(options: {
  classPrefix: string;
  showOverflowTrigger: boolean;
  actionMenuId: string;
  actionMenuTriggerId: string;
  actionsAriaLabel: string;
  open: boolean;
  actionMenuInitialFocusVisible: boolean;
  actionMenuSections: MenuSection[];
  closeActionMenu: () => void;
  finishActionMenuClose: (event: CustomEvent<void>) => void;
  handleActionSelect: (event: CustomEvent<MenuItemData>) => void;
}) {
  if (!options.showOverflowTrigger) return null;
  return (
    <ds-menu
      id={options.actionMenuId}
      class={className(options.classPrefix, 'action-menu')}
      anchorId={options.actionMenuTriggerId}
      align="end"
      menuLabel={options.actionsAriaLabel}
      open={options.open}
      initialFocusVisible={options.actionMenuInitialFocusVisible}
      sections={options.actionMenuSections}
      onDsClose={options.closeActionMenu}
      onDsAfterClose={options.finishActionMenuClose}
      onDsSelect={options.handleActionSelect}
    />
  );
}

import type { MenuItemData, MenuSection } from '../Menu/menu-types';
import type {
  BarTitleAction,
  BarTitleActionConfigItem,
  BarTitleActionItem,
  BarTitleDivider,
  BarTitleMenuChoiceItem,
  BarTitlePrimaryAction,
  BarTitleVariant,
} from './bar-title-types';

export type BarTitleActionPresentation = BarTitleVariant | 'mobile';

export function isBarTitleActionDivider(
  item: BarTitleActionConfigItem | BarTitleMenuChoiceItem
): item is BarTitleDivider {
  return 'type' in item && item.type === 'divider';
}

export function resolveBarTitleActionItems(
  actionItems: BarTitleActionConfigItem[] | undefined,
  primaryAction: BarTitlePrimaryAction | null,
  actions: BarTitleActionItem[]
): BarTitleActionConfigItem[] {
  if (actionItems !== undefined) return actionItems;

  const resolved: BarTitleActionConfigItem[] = [];
  if (primaryAction) {
    const { type, ...primary } = primaryAction;
    resolved.push({
      ...primary,
      type: 'button',
      buttonType: type,
      appearance: 'filled',
    });
  }
  for (const action of actions) {
    resolved.push(
      'type' in action
        ? action
        : {
            ...action,
            type: 'overflow',
          }
    );
  }
  return resolved;
}

function nestedChoices(item: BarTitleActionConfigItem): BarTitleMenuChoiceItem[] | undefined {
  return item.type === 'menu' || item.type === 'split' ? item.choices : undefined;
}

export function barTitleActionIdIssues(items: BarTitleActionConfigItem[]): string[] {
  const seen = new Set<string>();
  const issues: string[] = [];
  const visit = (id: string) => {
    if (!id.trim()) {
      issues.push('Action ids must be non-empty.');
      return;
    }
    if (seen.has(id)) {
      issues.push(`Duplicate action id: ${id}`);
      return;
    }
    seen.add(id);
  };

  for (const item of items) {
    if (isBarTitleActionDivider(item)) continue;
    visit(item.id);
    for (const choice of nestedChoices(item) ?? []) {
      if (!isBarTitleActionDivider(choice)) visit(choice.id);
    }
  }
  return issues;
}

function actionCollapses(
  item: BarTitleActionConfigItem,
  presentation: BarTitleActionPresentation
): boolean {
  if (isBarTitleActionDivider(item) || item.type === 'overflow') return false;
  if (presentation === 'mobile') {
    if (item.type !== 'icon') return true;
    return (item.mobile ?? 'auto') === 'overflow';
  }
  return presentation === 'constrained' && (item.collapse ?? 'auto') === 'auto';
}

export function visibleBarTitleActions(
  items: BarTitleActionConfigItem[],
  presentation: BarTitleActionPresentation
): BarTitleActionConfigItem[] {
  const primary = items.find(
    item =>
      !isBarTitleActionDivider(item) &&
      item.type !== 'overflow' &&
      !actionCollapses(item, presentation)
  );
  return primary ? [primary] : [];
}

function menuItem(action: BarTitleAction, includeIcon: boolean = true): MenuItemData {
  return {
    label: action.label,
    value: action.id,
    icon: includeIcon ? action.icon : undefined,
    isInactive: action.isInactive,
    isDestructive: action.isDestructive,
  };
}

function appendChoices(
  output: Array<MenuItemData | BarTitleDivider>,
  choices: BarTitleMenuChoiceItem[],
  includeIcons: boolean = true
) {
  for (const choice of choices) {
    output.push(isBarTitleActionDivider(choice) ? choice : menuItem(choice, includeIcons));
  }
}

function toSections(items: Array<MenuItemData | BarTitleDivider>): MenuSection[] {
  const sections: MenuSection[] = [];
  let current: MenuItemData[] = [];
  const commit = () => {
    if (current.length > 0) sections.push({ items: current });
    current = [];
  };

  for (const item of items) {
    if ('type' in item && item.type === 'divider') commit();
    else current.push(item as MenuItemData);
  }
  commit();
  return sections;
}

export function barTitleChoiceSections(choices: BarTitleMenuChoiceItem[]): MenuSection[] {
  const rows: Array<MenuItemData | BarTitleDivider> = [];
  appendChoices(rows, choices);
  return toSections(rows);
}

export function overflowBarTitleActionSections(
  items: BarTitleActionConfigItem[],
  presentation: BarTitleActionPresentation
): MenuSection[] {
  const rows: Array<MenuItemData | BarTitleDivider> = [];
  const [visibleAction] = visibleBarTitleActions(items, presentation);

  for (const item of items) {
    if (isBarTitleActionDivider(item)) {
      rows.push(item);
      continue;
    }
    if (item.type === 'overflow') {
      rows.push(menuItem(item, false));
      continue;
    }
    if (item === visibleAction) continue;

    if (item.type === 'menu') {
      appendChoices(rows, item.choices, false);
      continue;
    }
    if (item.type === 'split') {
      rows.push(menuItem(item, false));
      appendChoices(rows, item.choices, false);
      continue;
    }
    rows.push(menuItem(item, false));
  }

  return toSections(rows);
}

export function availableBarTitleActionMenuIds(
  visibleActions: BarTitleActionConfigItem[],
  showOverflowTrigger: boolean
): Set<string> {
  const ids = new Set<string>();
  if (showOverflowTrigger) ids.add('__overflow');
  for (const item of visibleActions) {
    if (!isBarTitleActionDivider(item) && (item.type === 'menu' || item.type === 'split')) {
      ids.add(item.id);
    }
  }
  return ids;
}

export function findBarTitleAction(
  items: BarTitleActionConfigItem[],
  id: string
): BarTitleAction | undefined {
  for (const item of items) {
    if (isBarTitleActionDivider(item)) continue;
    if (item.id === id) return item;
    const choice = nestedChoices(item)?.find(
      candidate => !isBarTitleActionDivider(candidate) && candidate.id === id
    );
    if (choice && !isBarTitleActionDivider(choice)) return choice;
  }
  return undefined;
}

import type { MenuItemData, MenuSection } from '../Menu/menu-types';
import type { TabItem } from '../TabGroup/tab-item-utils';
import {
  isBarTitleDivider,
  type BarTitleSection,
  type BarTitleSectionItem,
} from './bar-title-types';

export function selectableBarTitleSections(sections: BarTitleSectionItem[]): BarTitleSection[] {
  return sections.filter((item): item is BarTitleSection => !isBarTitleDivider(item));
}

export function effectiveBarTitleSectionValue(
  sections: BarTitleSectionItem[],
  value: string
): string {
  const selectable = selectableBarTitleSections(sections);
  return selectable.some(section => section.id === value) ? value : (selectable[0]?.id ?? '');
}

export function selectedBarTitleSectionLabel(
  sections: BarTitleSectionItem[],
  value: string
): string {
  const selectedId = effectiveBarTitleSectionValue(sections, value);
  return (
    selectableBarTitleSections(sections).find(section => section.id === selectedId)?.label ?? ''
  );
}

export function barTitleSectionTriggerAriaLabel(
  sectionsAriaLabel: string,
  selectedLabel: string
): string {
  return `${sectionsAriaLabel}. Current section: ${selectedLabel}`;
}

export function barTitleSectionMenuSections(
  sections: BarTitleSectionItem[],
  selectedId: string
): MenuSection[] {
  const groups: MenuSection[] = [];
  let items: MenuItemData[] = [];
  const commit = () => {
    if (items.length > 0) groups.push({ items });
    items = [];
  };

  for (const item of sections) {
    if (isBarTitleDivider(item)) {
      commit();
    } else {
      items.push({
        label: item.label,
        value: item.id,
        isSelected: item.id === selectedId,
        isInactive: item.isInactive,
      });
    }
  }
  commit();
  return groups;
}

export function barTitleSectionsToTabs(sections: BarTitleSectionItem[]): TabItem[] {
  return sections.map(item =>
    isBarTitleDivider(item)
      ? { type: 'divider' }
      : {
          id: item.id,
          label: item.label,
          isInactive: item.isInactive,
        }
  );
}

export function barTitleSectionsDigest(sections: BarTitleSectionItem[] | undefined): string {
  return (sections ?? [])
    .map(item =>
      isBarTitleDivider(item) ? '|' : `${item.id}\0${item.label}\0${item.isInactive ? '1' : '0'}`
    )
    .join('\n');
}

import type { ButtonFilledContrast, ButtonFilledIntent } from '../ButtonFilled/ButtonFilled';

export interface BarTitleSection {
  id: string;
  label: string;
  isInactive?: boolean;
}

export interface BarTitleDivider {
  type: 'divider';
}

export type BarTitleSectionItem = BarTitleSection | BarTitleDivider;

export interface BarTitleAction {
  id: string;
  label: string;
  ariaLabel?: string;
  icon?: string;
  isInactive?: boolean;
  isDestructive?: boolean;
}

export interface BarTitlePrimaryAction extends BarTitleAction {
  intent?: ButtonFilledIntent;
  contrast?: ButtonFilledContrast;
  isLoading?: boolean;
  type?: 'button' | 'submit' | 'reset';
  collapse?: BarTitlePrimaryActionCollapse;
}

export type BarTitleActionItem = BarTitleAction | BarTitleDivider;

export type BarTitleActionAppearance = 'filled' | 'unfilled';
export type BarTitleActionCollapse = 'auto' | 'never';
export type BarTitleActionMobile = 'auto' | 'visible' | 'overflow';

interface BarTitleVisibleActionBase extends BarTitleAction {
  appearance?: BarTitleActionAppearance;
  intent?: ButtonFilledIntent;
  contrast?: ButtonFilledContrast;
  isLoading?: boolean;
  buttonType?: 'button' | 'submit' | 'reset';
  /** Auto moves the action into overflow only in constrained presentation. */
  collapse?: BarTitleActionCollapse;
  /**
   * Mobile defaults icon actions to visible and all labeled actions to overflow.
   * `visible` is supported only by icon actions.
   */
  mobile?: BarTitleActionMobile;
}

/** Visible labeled command in the authored action order. */
export interface BarTitleButtonAction extends BarTitleVisibleActionBase {
  type: 'button';
}

/** Visible icon-only command. ariaLabel is required because label is not rendered. */
export interface BarTitleIconAction extends BarTitleVisibleActionBase {
  type: 'icon';
  icon: string;
  ariaLabel: string;
}

export type BarTitleMenuChoice = BarTitleAction;
export type BarTitleMenuChoiceItem = BarTitleMenuChoice | BarTitleDivider;

/** Visible labeled menu button. Selecting a choice emits that choice's flat id. */
export interface BarTitleMenuAction extends BarTitleVisibleActionBase {
  type: 'menu';
  choices: BarTitleMenuChoiceItem[];
  menuAriaLabel?: string;
}

/** Command with a dedicated menu segment; defaults filled when appearance is omitted. */
export interface BarTitleSplitAction extends BarTitleVisibleActionBase {
  type: 'split';
  choices: BarTitleMenuChoiceItem[];
  menuAriaLabel: string;
}

/** Command that is always presented in the shared overflow menu. */
export interface BarTitleOverflowAction extends BarTitleAction {
  type: 'overflow';
}

/**
 * Ordered page-header action model. IDs must be non-empty and unique across
 * top-level actions and every nested menu choice. At most the first eligible
 * action renders beside the title; remaining actions use the text-only overflow.
 */
export type BarTitleActionConfigItem =
  | BarTitleButtonAction
  | BarTitleIconAction
  | BarTitleMenuAction
  | BarTitleSplitAction
  | BarTitleOverflowAction
  | BarTitleDivider;

export type BarTitleVariant = 'expanded' | 'compact' | 'constrained';
export type BarTitlePlacement = 'page' | 'shell-bar';

export type BarTitlePrimaryActionCollapse = 'auto' | 'never';

export function isBarTitleDivider(
  item: BarTitleSectionItem | BarTitleActionItem
): item is BarTitleDivider {
  return 'type' in item && item.type === 'divider';
}
